// Rusted Steel - color. STATIC (no t/u_time). Runs INSIDE shadeSurface().
// Brushed steel (fine streaks along the horizontal), rust in the noise patches with
// a dark corrosion front around them, and orange stains running DOWN from every
// patch (sampled above the point: if there is rust above, it has dripped here).
// In scope: pModel, n_model, viewDir_model, mainLight_model.
// Dock colors: u_col1 = steel, u_col2 = rust.

float SCALE = 2.2 * max(E, 0.05);         // slider E   // MUST match the displacement
float COVER = clamp(0.45 * F, 0.0, 1.0);  // slider F
float STAINS = 0.6;    // strength of the rust stains running down     [0 .. 1]
float BRUSH  = 0.18;   // contrast of the brushed streaks              [0 .. 0.4]

float th = mix(0.78, 0.22, COVER);

// rust mask at the point (k = 0) and at 4 points above it (k = 1..4, stains)
float rustHere = 0.0;
float rnHere = 0.0;
float stain = 0.0;
for (int k = 0; k < 5; k++) {
    vec3 np = (pModel + vec3(0.0, 0.07 * float(k), 0.0)) * SCALE;
    float rn = 0.0;
    float ra = 0.5;
    for (int oct = 0; oct < 3; oct++) {
        vec3 ip = floor(np);
        vec3 fr = fract(np);
        vec3 w  = fr * fr * (3.0 - 2.0 * fr);
        float h000 = fract(sin(dot(ip + vec3(0.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
        float h100 = fract(sin(dot(ip + vec3(1.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
        float h010 = fract(sin(dot(ip + vec3(0.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
        float h110 = fract(sin(dot(ip + vec3(1.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
        float h001 = fract(sin(dot(ip + vec3(0.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
        float h101 = fract(sin(dot(ip + vec3(1.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
        float h011 = fract(sin(dot(ip + vec3(0.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
        float h111 = fract(sin(dot(ip + vec3(1.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
        float z0 = mix(mix(h000, h100, w.x), mix(h010, h110, w.x), w.y);
        float z1 = mix(mix(h001, h101, w.x), mix(h011, h111, w.x), w.y);
        rn += ra * mix(z0, z1, w.z);
        np *= 2.03;
        ra *= 0.5;
    }
    rn /= 0.875;
    float r = smoothstep(th, th + 0.06, rn);
    if (k == 0) { rustHere = r; rnHere = rn; }
    else        stain = max(stain, r * (1.0 - 0.2 * float(k)));
}

// streaks: smooth 1D noise ACROSS the streak direction, constant along it.
// Brushing runs horizontally (index = height y, gently wavy); the stains run down
// (index = angle around the vertical axis).
float yb = pModel.y * 170.0 + 2.5 * sin(pModel.x * 2.1 + pModel.z * 1.7);
float yi = floor(yb);
float yf = smoothstep(0.0, 1.0, fract(yb));
float brush = mix(fract(sin(yi * 12.9898) * 43758.5453),
                  fract(sin((yi + 1.0) * 12.9898) * 43758.5453), yf);
float ab = atan(pModel.z, pModel.x) * 70.0;
float ai = floor(ab);
float af = smoothstep(0.0, 1.0, fract(ab));
float streak = mix(fract(sin(ai * 78.233) * 43758.5453),
                   fract(sin((ai + 1.0) * 78.233) * 43758.5453), af);

// --- steel
vec3 steel = ubuf.u_col1 * (1.0 - BRUSH * 0.5 + BRUSH * brush);
float fres = pow(1.0 - max(dot(n_model, viewDir_model), 0.0), 3.0);
steel += ubuf.u_col1 * 0.25 * fres;

// --- rust: darker and redder in the thick crust, brighter orange at the surface
vec3 grit = floor(pModel * 90.0);
float g = fract(sin(dot(grit, vec3(12.99, 78.23, 37.71))) * 43758.5453);
vec3 rustCol = mix(ubuf.u_col2 * 0.45, ubuf.u_col2 * 1.25, clamp((rnHere - th) * 2.5 + 0.3 * g, 0.0, 1.0));

// dark corrosion front just outside each patch
float front = smoothstep(th - 0.07, th, rnHere) * (1.0 - rustHere);

vec3 col = mix(steel, steel * 0.45 + ubuf.u_col2 * 0.15, front);
// stains: only outside the rust, streaky, fading away from the patch
col = mix(col, ubuf.u_col2 * 0.9, STAINS * stain * (1.0 - rustHere) * (0.4 + 0.6 * streak));
col = mix(col, rustCol, rustHere);

textureCol = col;

