// Rusted Steel - relief (displacement). STATIC (no t/u_time). Runs INSIDE map().
// Brushed steel eaten by rust: the rust is a threshold of a fractal noise, its crust
// stands a little proud of the steel and is pitted by small craters.
// In scope: d_surf, p, pModel.  Convention: d_surf -= height -> raised.
//
// SPEED. Crust and pits are a few thousandths high, so the noise runs only inside a
// BAND around the surface, with the relief faded to zero at the edge of the band
// (smooth, the field stays continuous). Far from the surface -- where a missed ray
// spends ~100 steps -- this costs one smoothstep.

float SCALE = 2.2 * max(E, 0.05);         // slider E   // patch frequency      [1 .. 6]
float COVER = clamp(0.45 * F, 0.0, 1.0);  // slider F   // rusted share         [0 .. 1]
float CRUST = 0.010;   // crust thickness (field units)                         [0 .. 0.02]
float PITS  = 0.004;   // pit depth (field units)                               [0 .. 0.008]

float BAND   = 0.3;
float inBand = 1.0 - smoothstep(0.5 * BAND, BAND, abs(d_surf));

if (inBand > 0.0) {
    // --- rust mask: 3 octaves of value noise (SAME as the color)
    vec3 np = pModel * SCALE;
    float rn = 0.0;
    float ra = 0.5;
    for (int oct = 0; oct < 3; oct++) {
        vec3 ip = floor(np);
        vec3 fr = fract(np);
        vec3 w  = fr * fr * (3.0 - 2.0 * fr);
        float h000 = fract(sin(dot(ip + vec3(0.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
        float h100 = fract(sin(dot(ip + vec3(1.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
        float h010 = fract(sin(dot(ip + vec3(0.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
        float h110 = fract(sin(dot(ip + vec3(1.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
        float h001 = fract(sin(dot(ip + vec3(0.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
        float h101 = fract(sin(dot(ip + vec3(1.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
        float h011 = fract(sin(dot(ip + vec3(0.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
        float h111 = fract(sin(dot(ip + vec3(1.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
        float z0 = mix(mix(h000, h100, w.x), mix(h010, h110, w.x), w.y);
        float z1 = mix(mix(h001, h101, w.x), mix(h011, h111, w.x), w.y);
        rn += ra * mix(z0, z1, w.z);
        np *= 2.03;
        ra *= 0.5;
    }
    rn /= 0.875;
    float th   = mix(0.78, 0.22, COVER);
    float rust = smoothstep(th, th + 0.06, rn);

    // --- pits: one octave of fine value noise, only inside the rust
    vec3 qp = pModel * 38.0;
    vec3 qi = floor(qp);
    vec3 qf = fract(qp);
    vec3 qw = qf * qf * (3.0 - 2.0 * qf);
    float q000 = fract(sin(dot(qi + vec3(0.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float q100 = fract(sin(dot(qi + vec3(1.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float q010 = fract(sin(dot(qi + vec3(0.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float q110 = fract(sin(dot(qi + vec3(1.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float q001 = fract(sin(dot(qi + vec3(0.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float q101 = fract(sin(dot(qi + vec3(1.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float q011 = fract(sin(dot(qi + vec3(0.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float q111 = fract(sin(dot(qi + vec3(1.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float qn = mix(mix(mix(q000, q100, qw.x), mix(q010, q110, qw.x), qw.y),
                   mix(mix(q001, q101, qw.x), mix(q011, q111, qw.x), qw.y), qw.z);
    float pit = smoothstep(0.62, 0.88, qn) * rust;

    // crust a bit lumpy: thicker where the noise is high
    float crust = rust * (0.7 + 0.6 * (rn - th));

    d_surf -= (CRUST * crust - PITS * pit) * inBand;
}
